let analysisRequest=0;
async function ensureAnalysisData(force=false){
 const codes=analysisModel().funds.map(f=>f.code),wanted=S.analysisFund.replace(/^fund/,''),key=[codes.join('|'),wanted,S.analysisPeer].join(':');if(!codes.length)return;
 if(force){v7Store.reset();D.v7Key=null;}if(D.v7Key===key)return;const request=++analysisRequest;D.v7Key=key;D.v7=null;D.v7Error=null;
 try{let data=await v7Store.load([...new Set([...codes,...(S.analysisPeer?[S.analysisPeer]:[])])]);if(request!==analysisRequest)return;
  const current=codes.includes(wanted)?wanted:codes[0],first=data.research?.funds?.[current]?.peers?.[0]?.code;
  if(!S.analysisPeer&&first){data=await v7Store.load([...new Set([...codes,first])]);if(request!==analysisRequest)return;S.analysisPeer=first;D.v7Key=[codes.join('|'),wanted,first].join(':');}
  D.v7=data;if(S.view==='analysis')render();
 }catch(e){if(request===analysisRequest){D.v7Error=e.message;if(S.view==='analysis')render();}}
}
function viewAnalysis(){const m=analysisModel();if(m.funds.length)ensureAnalysisData();return renderAnalysisV16(m,S.bounds,D.v7,{...S,analysisError:D.v7Error,analysisQuestion:S.aiQuestions.analysis||''});}
function objectList(mode){const m=model(),held=mode==='fund'?m.funds:m.companies;const extra=S.view==='discussion'?D.discussionOptions[mode]:D.timelineOptions[mode];return [...new Map([...held,...extra].map(x=>[x.id,x])).values()];}
