async function searchTimeline(input){const q=input.value,found=await searchObjects(input,'timeline',S.timelineMode);if(!input.isConnected||q!==input.value)return;const norm=x=>String(x).replace(/\s/g,'').toLowerCase(),exact=(found||[]).filter(x=>norm(x.code)===norm(q)||norm(x.name)===norm(q));if(exact.length===1&&S.timelineId!==exact[0].id)return selectTimeline(exact[0].id);}
async function selectTimeline(id){S.timelineId=id;S.newsPage=0;S.selected.clear();S.activityLoading=id;render();try{if(id)await loadObjectStreams(id);}finally{if(S.timelineId===id){S.activityLoading='';if(S.view==='news')render();}}}
function selector(mode,id,searchText,prefix){const list=objectList(mode).filter(x=>[x.name,x.code].join(' ').toLowerCase().includes(searchText.toLowerCase()));return `<div class="v8-object-picker"><input aria-label="搜索${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-search value="${h(searchText)}" placeholder="搜索基金或股票"><select aria-label="选择${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-object><option value="">选择${mode==='fund'?'基金':'公司'}</option>${opts(list.map(x=>[x.id,x.name+' · '+x.code]),id)}</select></div>`;}
function viewTimeline(){const m=timelineModel(),id=S.timelineId;const allEvents=id?eventSelection(D.events,m,S.timelineMode,id,today(),S.older):portfolioEvents(D.events,model(),S.timelineMode,today(),S.older);S.newsPage=Math.min(S.newsPage,Math.max(0,Math.ceil(allEvents.length/50)-1));const scoped=allEvents.filter(e=>!id||S.timelineScope==='related'||S.timelineMode!=='fund'||(S.timelineScope==='direct')===(e.entities||[]).some(t=>t.kind==='fund'&&'fund'+t.code===id));const events=scoped.slice(S.newsPage*50,(S.newsPage+1)*50);return `<div class="v8-sectionhead"><h1 class="v7-h1">事件时间轴</h1>${D.eventUpdatedAt?`<small class="v8-muted">资料更新 ${h(String(D.eventUpdatedAt).slice(0,10))}</small>`:''}</div><div class="v8-tabs">${btn('timeline-mode','按基金','fund',S.timelineMode==='fund'?'on':'')}${btn('timeline-mode','按公司','company',S.timelineMode==='company'?'on':'')}</div>${selector(S.timelineMode,id,S.timelineSearch,'timeline')}${id?`<div class="v7-actions">${btn('object-profile','基础信息',id)}${S.timelineMode==='fund'?['related','direct','holdings'].map((v,i)=>btn('timeline-scope',['全部相关','基金自身','持仓公司'][i],v,S.timelineScope===v?'v7-btn primary':'v7-btn')).join(''):''}</div>`:''}
 ${(id||model().funds.length)?`<div class="v8-sectionhead"><span class="v8-muted">${id?(objectCards.get(id)?.name||'所选对象'):'我的持仓'} · ${S.older?'已收录事件':'近30天'} · ${scoped.length} 条</span></div><ol class="v7-timeline">${events.map(e=>`<li><time>${h(e.date)} · ${h(e.source)}${e.topics?.length?' · '+h(e.topics.map(t=>t.label).join(' / ')):''}</time><p class="v13-entities">${id&&S.timelineMode==='fund'?`<span>${(e.entities||[]).some(t=>t.kind==='fund'&&'fund'+t.code===id)?'基金自身公告／动态':'持仓公司相关 · '+h(m.funds.find(f=>f.id===id)?.disclosure?.asOf||'报告日未接入')}</span>`:''}${eventLabels(e)}</p><h4>${h(e.title)}</h4>${e.summary?`<p>${h(e.summary)}</p>`:''}${e.analysis?.points?.length?`<details><summary>AI 整理</summary>${e.analysis.points.map(p=>`<p>${h(p.text)}</p>`).join('')}</details>`:''}<div class="v7-actions">${btn('read-event','正文',e.id,'v7-link')}${ext(e.url,'原文')}${btn('collect-event','收藏',e.id,'v7-link')}<label><input type="checkbox" data-event-pick="${h(e.id)}" ${S.selected.has(e.id)?'checked':''}>选择</label></div></li>`).join('')||`<li class="v8-muted">${S.activityLoading===id?'正在读取…':'暂未收录'}</li>`}</ol>${scoped.length>50?`<div class="v7-actions">${S.newsPage?btn('news-page','上一页','-1'):''}<span>${S.newsPage+1} / ${Math.ceil(scoped.length/50)}</span>${(S.newsPage+1)*50<scoped.length?btn('news-page','下一页','1'):''}</div>`:''}${events.length?`<button class="v7-btn" data-act="ai-summary" ${S.selected.size?'':'disabled'}>摘要所选事件</button>`:''}`:''}`;}
function portfolioIds(m=model()){return new Set([...m.funds,...m.companies].map(x=>x.id));}
function portfolioEvents(events,m,mode,day,older=false){return [...new Map((mode==='fund'?m.funds:m.companies).flatMap(x=>eventSelection(events,m,mode,x.id,day,older)).map(x=>[x.id,x])).values()].sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));}
function sourceRows(objectId=S.sourceId){const obj=objectId;return sortSources(allSourceRows().filter(s=>s.visibility!=='internal'&&(sourceCadence(s)!=='news'||s.kind==='disclosure')&&(obj?s.entities.some(id=>id===obj||'stock'+D.reference.nodes.find(n=>n.id===id)?.code===obj):!model().funds.length||s.entities.some(id=>portfolioIds().has(id)||portfolioIds().has('stock'+D.reference.nodes.find(n=>n.id===id)?.code)))&&[s.title,s.publisher,s.summary,s.period].join(' ').toLowerCase().includes(S.sourceQuery.toLowerCase())));}
