function viewDiscussion(){const mode=S.discussionId.startsWith('stock')?'company':'fund',id=S.discussionId,m=objectModel(id),obj=[...m.funds,...m.companies,...objectCards.values()].find(x=>x.id===id),owned=discussionIds(m,id);if(!S.forumDateTouched)S.forumDay=readableDiscussionDay(D.forum.records||[],owned,S.forumDay,today());for(const objectId of owned){ensureForum(objectId);loadCachedForum(objectId,S.forumDay);}const rows=discussionRows(D.forum.records||[],owned,S.forumDay);return `<h1 class="v7-h1">帖子与评论</h1><div class="v8-tabs">${btn('discussion-mode','基金','fund',mode==='fund'?'on':'')}${btn('discussion-mode','公司','company',mode==='company'?'on':'')}</div>${selector(mode,id,S.discussionSearch,'discussion')}${obj?`<div class="v7-actions">${ext('https://guba.eastmoney.com/list,'+(mode==='fund'?'of':'')+obj.code+'.html','原始讨论区')}${btn('object-profile','基础信息',id)}</div>`:''}<div class="v7-actions"><label>日期 <input type="date" id="forum-date" value="${h(S.forumDay)}" max="${today()}"></label>${btn('forum-read-all','补读全部遗漏')}${btn('forum-read-page','补读本页遗漏')}${btn('forum-analyze','分析所选帖子')}${btn('forum-select-all','选择本页')}</div>${readingBatchMarkup()}${forumStatusMarkup(id)}${rows.map(r=>`<article class="v7-card"><small class="v8-muted">${h(r.date)} · ${h(r.source)} · ${h(objectCards.get(r.objectId)?.name||m.companies.find(x=>x.id===r.objectId)?.name||D.funds.find(f=>f.id===r.objectId)?.name||r.objectId)}${r.boardVerified?'':' · 关联待核'}${r.coverage?.body==='complete'?'':' · 正文待取得'}</small><h3>${h(r.title)}</h3>${r.content?`<details><summary>帖子正文</summary><p class="v11-post-text">${h(r.content)}</p></details>`:''}<details><summary>评论 · ${r.comments?.length?'已取得 '+r.comments.length+(r.coverage?.comments==='complete'?'':' · 继续读取'):r.coverage?.comments==='complete'?'暂无评论':'待取得'}</summary>${(r.comments||[]).map(c=>`<p><small>${h(c.at||'')}${c.replyTo?' · 回复':''}</small><br>${h(c.text)}</p>`).join('')}</details><div class="v7-actions">${ext(r.url,'原帖')}${r.coverage?.body!=='complete'||r.coverage?.comments!=='complete'?btn('forum-fetch','补读本帖遗漏',r.id,'v7-link'):''}${btn('collect-forum','收藏帖子与评论',r.id,'v7-link')}<label><input type="checkbox" data-forum-pick="${h(r.id)}" ${S.forumSelected.has(r.id)?'checked':''}>选择</label></div></article>`).join('')||`<p class="v8-muted">${S.activityLoading?'正在读取…':'暂未取得帖子'}</p>`}<section class="v7-card"><h2>说法核对</h2><form id="verify-form"><label class="v7-field"><textarea name="claim" rows="3" placeholder="输入需要核对的具体说法" required maxlength="2000"></textarea></label><button class="v7-btn primary">核对</button></form></section>`;}

function viewSettings(){return `<h1 class="v7-h1">设置</h1><section class="v7-card"><h2>AI 服务</h2><form id="settings-form"><label class="v7-field"><span>使用方式</span><select name="mode">${opts([['shared','默认 AI'],['custom','自选 AI']],S.cfg.mode)}</select></label><p class="v8-muted">${S.sharedAvailable?'默认 AI 可用':'默认 AI 尚未配置'}</p><details ${S.cfg.mode==='custom'?'open':''}><summary>自选 AI 配置</summary><label class="v7-field"><span>接口地址</span><input name="url" type="url" value="${h(S.cfg.url)}" placeholder="API 站点或完整接口地址"></label><label class="v7-field"><span>API Key</span><input name="key" type="password" autocomplete="off" value="${h(S.cfg.key)}"></label><label class="v7-field"><span>模型名称</span><input name="model" value="${h(S.cfg.model)}"></label></details><button class="v7-btn primary">保存</button></form></section><section class="v7-card"><h2>持仓备份</h2><div class="v7-actions">${btn('export-account','导出持仓')}${btn('import-account','导入持仓')}<input id="account-file" type="file" accept="application/json" hidden></div></section>`;}

function evidenceMaterials(objectId=S.sourceId,question=''){
 const words=[...new Set((question.match(/[a-zA-Z0-9]{2,}|[\u4e00-\u9fff]{2,}/g)||[]).flatMap(w=>w.length>4?[w,...Array.from({length:w.length-1},(_,i)=>w.slice(i,i+2))]:[w]))];
 const sourceList=sourceRows(objectId).map(s=>({s,score:words.reduce((n,w)=>n+(s.title.includes(w)?1:0),0)+(s.holdings||s.navObservation?0.2:0)})).sort((a,b)=>b.score-a.score).slice(0,24).map(({s})=>({id:s.id,text:[s.title,s.publishedAt,s.period,s.locator,s.contentCoverage==='link-only'?'仅标题及原文入口，正文未读取':'',...sourceHighlights(s).map(i=>i.text),...(s.holdings||[]).map(r=>`${r.code} ${r.name}：${r.weightPercent===null?'占比待核':r.weightPercent+'%'}（占基金净资产）`),s.navObservation?'净值来源观察，尚未核为总回报；'+JSON.stringify(s.navObservation.snapshot||{}):''].filter(Boolean).join('\n'),url:safeUrl(s.url),date:s.publishedAt||s.period||null,locator:s.locator||''}));
 const recent=objectId?eventSelection(D.events,objectModel(objectId),objectId.startsWith('fund')?'fund':'company',objectId,today()).slice(0,6):[];
 return [...sourceList,...recent.map(e=>({id:e.id,text:[e.date,e.title,e.summary,e.contentCoverage==='title-only'?'仅标题，正文未读取':''].filter(Boolean).join(' '),url:safeUrl(e.url),date:e.date,locator:''}))];
}
function currentRecentAI(scope=S.view){const job=aiJobs?.latestComplete(scope);if(job)return {value:job.value,entry:job.saved?library.aiEntry(job.value.libraryEntryId):null};const entry=library?.latestAI(scope);return entry?{value:{...entry.aiResult,saved:true},entry}:null;}
function paintAIStatus(){
 if(!aiJobs)return;
 for(const el of document.querySelectorAll('[data-ai-scope]')){const scope=el.dataset.aiScope,job=aiJobs.latest(scope);el.classList.toggle('is-running',Boolean(job&&['running','queued'].includes(job.status)));el.innerHTML=job?h(job.message)+(job.status==='complete'?btn('show-ai-job','查看结果',job.id,'v15-text-link'):''):'';
  let host=el.parentElement.querySelector('[data-ai-recent]');if(!host){host=document.createElement('div');host.dataset.aiRecent=scope;el.insertAdjacentElement('afterend',host);}
  const latest=currentRecentAI(scope),key=latest?JSON.stringify([latest.value.libraryEntryId,latest.value.createdAt,latest.entry?.updatedAt]):'';
  if(host.dataset.resultKey!==key){host.innerHTML=latest?recentAIResult(latest.value,latest.entry):'';host.dataset.resultKey=key;
   if(latest?.entry){const area=host.querySelector('textarea');if(area&&S.aiNoteDrafts?.[latest.entry.id]!==undefined)area.value=S.aiNoteDrafts[latest.entry.id];}}
 }
}
function notifyAIComplete(job){
 let region=$('#ai-completion-notices');if(!region){region=document.createElement('aside');region.id='ai-completion-notices';region.setAttribute('aria-label','任务完成提醒');region.setAttribute('aria-live','polite');document.body.append(region);}
 const notice=document.createElement('section');notice.className='v18-ai-notice';notice.dataset.aiNotice=job.id;notice.innerHTML=`<div><strong>AI分析已完成</strong><p>${h(job.value.result.title)}</p><small>${job.saved?'已自动保存到我的资料库 · AI解读':'结果可查看，请复制或收藏保存'}</small></div><div class="v7-actions">${btn('show-ai-job','查看分析',job.id,'v7-btn primary')}${btn('dismiss-ai-notice','关闭提醒',job.id,'v15-text-link')}</div>`;region.append(notice);while(region.children.length>3)region.firstElementChild.remove();
}
function showAIResult(){if(!S.ai)return;const entry=library.aiEntry(S.ai.libraryEntryId);dialog(S.ai.result.title,aiResultBody(S.ai)+`${entry?`<form class="v18-ai-note" data-ai-note-form="${h(entry.id)}"><label class="v7-field"><span>我的笔记</span><textarea name="note" rows="3" maxlength="20000">${h(S.aiNoteDrafts?.[entry.id]??entry.note)}</textarea></label><button class="v7-btn primary">保存笔记</button></form>`:''}<div class="v7-actions"><span class="v15-progress-note">${h(S.ai.saved===false?'请复制保存结果':'已自动保存到我的资料库 · AI解读')}</span>${btn('organize-ai','收藏与分类')}${btn('ai-library','在资料库查看')}${btn('copy-ai','复制结果')}</div>`);}
function organizeAI(value){const entry=library.aiEntry(value.libraryEntryId);return library.collect(entry||{title:value.result.title,excerpt:[value.result.overview?.text,...value.result.points.map(p=>p.text)].filter(Boolean).join('\n\n'),aiResult:value,referenceId:'ai:'+value.libraryEntryId});}
function aiTitle(task,scope=S.view){const names={news_summary:'事件摘要',news_impact:'事件与持仓关联',news_differences:'事件要点与分歧',news_ask:'事件问答',analysis_module:moduleById(S.analysisModule)[1]+'解读',analysis_overview:'组合整体解读',analysis_cost:'相似基金比较解读',analysis_history:'持有体验解读',analysis_ask:'持仓分析问答'};const selected=scope==='analysis'?((task==='analysis_cost'||task!=='analysis_overview'&&(['peers','fees','changes'].includes(S.analysisModule)||['experience','drawdown'].includes(S.analysisModule)&&S.historyScope==='fund'))?(analysisModel().funds.find(f=>f.id===S.analysisFund)||analysisModel().funds[0]):null):objectCards.get(scope==='news'?S.timelineId:scope==='sources'?S.sourceId:S.discussionId);return (names[task]||({sources:'资料解读',discussion:'帖子与评论解读',library:'收藏资料解读'}[scope])||'AI解读')+' · '+(selected?.name||(scope==='analysis'?'当前组合':scope==='library'?'所选收藏':'我的持仓'));}
function startAI({task,materials=[],question='',scope=S.view,work}){if(S.cfg.mode==='custom'&&(!S.cfg.url||!S.cfg.key||!S.cfg.model))return toast('请在设置中填写模型接口');const cfg=structuredClone(S.cfg),title=aiTitle(task,scope),key=JSON.stringify([scope,task,materials.map(x=>[x.id,x.text||'']),question]);if($('#v7-dialog').open)close();const job=aiJobs.start({scope,title,key,work:async progress=>{const value=work?await work(cfg,progress):{result:await requestAI(cfg,task,materials,question),materials};const generated=value.result.title;value.result.title=value.result.quality?.kind==='source-excerpts'?title+' · 原文要点':['summary','qa','verify'].includes(task)&&generated&&!['摘要','问题','模型结果'].includes(generated)?(title+' · '+generated).slice(0,180):title;value.task=task;return value;}});paintAIStatus();return job.promise;}
function runAI(task,materials,question=''){if(task.startsWith('analysis_'))materials=selectResearchMaterials(materials,task,S);if(!materials.length&&task!=='verify')return toast('请选择资料');return startAI({task,materials,question});}
function currentAnalysisMaterials(){return researchMaterials(analysisModel(),D.v7,S);}
async function readEvent(id){const e=D.events.find(x=>x.id===id);if(!e)return;toast('正在读取正文…');try{const x=await eventBody(e);dialog(e.title,`<p class="v8-muted">${h(e.date)} · ${h(e.source)}</p><div class="v15-article-body">${h(x.body)}</div><div class="v7-actions">${ext(e.url,'原文')}${btn('collect-event','收藏',id)}</div>`);}catch(err){toast(err.message);}}

