function syncEditor(){for(const el of document.querySelectorAll('[data-amount-index]'))editingRows[Number(el.dataset.amountIndex)].amount=el.value;}
function saveAccount(rows){S.analysisFund='';S.analysisPeer='';D.v7Key=null;analysisRequest++;const value={...normalizeAmounts(rows),savedAt:new Date().toISOString()};if(put('zhijian-holdings-v08',value)){S.account=value;S.accountLoading=Boolean(value.items.length);S.focus='portfolio';S.detail='portfolio';S.timelineId='';close();render();loadAccountObjects();toast('持仓已保存');}}
async function onSubmit(e){if(e.target.matches('[data-ai-note-form]')){e.preventDefault();const id=e.target.dataset.aiNoteForm,note=new FormData(e.target).get('note');if(library.saveAINote(id,note)){delete S.aiNoteDrafts?.[id];paintAIStatus();toast('笔记已保存到这份分析');}else toast('笔记保存失败，请复制后重试');return;}const form=e.target,id=form.id;if(!['v15-analysis-ai-form','v7-ai-form','holding-form','quick-add-form','inline-holding-form','target-form','ai-workbench','scenario-form','bounds-form','settings-form','verify-form','qa-form'].includes(id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(e.submitter?.name)data[e.submitter.name]=e.submitter.value;try{
 if(id==='holding-form'){syncEditor();return saveAccount(editingRows);}
 if(id==='v15-analysis-ai-form'){if(!D.v7)return toast('正在读取分析数据');return runAI('analysis_ask',fitMaterials(currentAnalysisMaterials()),data.question);}
 if(id==='v7-ai-form'){if(!D.v7)return toast('请先读取分析数据');return runAI('analysis_ask',fitMaterials(currentAnalysisMaterials()),data.question);}
 if(id==='inline-holding-form')return saveAccount(S.account.items.map(r=>r.code===form.dataset.code?{...r,amount:data.amount}:r));
 if(id==='target-form'){const m=model(),weights=Object.fromEntries(Object.entries(data).map(([id,x])=>[id,Number(x)]));validateTargets(m,weights);const baseline={};for(const f of m.funds){const n=f.observations?.snapshot;if(n&&Number.isFinite(n.nav)&&n.nav>0)baseline[f.id]={amount:f.amount,nav:n.nav,date:n.date};}const goal={weights,baseline,savedAt:new Date().toISOString()};if(put('zhijian-targets-v13',goal)){S.goal=goal;render();toast('已保存目标与参考值');}return;}
 if(id==='ai-workbench')return pageAI(data);
 if(id==='quick-add-form'){const items=structuredClone(S.account.items),existing=items.find(x=>x.code===addingFund[0]);if(existing)existing.amount=data.amount;else items.push({code:addingFund[0],name:addingFund[1],type:addingFund[2],amount:data.amount});return saveAccount(items);}
 if(id==='settings-form'){if(put('zhijian-v07-cfg',data)){S.cfg=data;toast('已保存');}return;}
 if(id==='bounds-form'){const value={};for(const [k,v]of Object.entries(data)){value[k]=v===''?null:Number(v);if(value[k]!==null&&(!Number.isFinite(value[k])||value[k]<0||k==='loss'&&value[k]===0||['fund','company'].includes(k)&&value[k]>100||k==='horizon'&&(value[k]<1||value[k]>600)))throw Error('上限数值无效');}if(put('zhijian-boundaries-v08',value)){S.bounds=value;render();toast('已保存');}return;}
 if(id==='scenario-form'){const m=model(),shock=Number(data.shock);if(!Number.isFinite(shock)||shock< -100||shock>100)throw Error('涨跌幅须为−100%至100%');const share=data.scope==='all'?100:m.funds.find(f=>f.id===data.scope)?.share??m.companies.find(c=>c.id===data.scope)?.share;if(!Number.isFinite(share))throw Error('请选择对象');const amount=m.total*share/100*shock/100;$('#scenario-result').innerHTML=`<div class="v8-metrics">${metric('组合变化',pct(share*shock/100))}${metric('金额变化',cash(amount))}</div>${S.bounds.loss!==null?`<small>${Math.max(0,-amount)>S.bounds.loss?'超过损失关注金额':'未超过损失关注金额'}</small>`:''}`;return;}
 if(id==='verify-form')return runAI('verify',evidenceMaterials(S.discussionId,data.claim),String(data.claim).replace(/@\S+/g,'').trim());
 if(id==='qa-form'){await loadObjectStreams(S.sourceId);return runAI('qa',evidenceMaterials(S.sourceId,data.question),data.question);}
 }catch(err){toast(err.message);}}
async function onChange(e){const el=e.target;if(el.id==='overlap-fund-a'||el.id==='overlap-fund-b'){S[el.id==='overlap-fund-a'?'overlapA':'overlapB']=el.value;S.overlapMode='pair';return render();}if(el.id==='v16-peer-select'){S.analysisPeer=el.value;return ensureAnalysisData();}if(el.id==='v7-analysis-fund'){S.analysisFund=el.value;S.analysisPeer='';return render();}if(el.dataset.sourcePick){el.checked?S.selected.add(el.dataset.sourcePick):S.selected.delete(el.dataset.sourcePick);return;}if(el.id==='forum-date'){S.forumDay=el.value;S.forumDateTouched=true;S.forumSelected.clear();return render();}if(el.dataset.forumPick){el.checked?S.forumSelected.add(el.dataset.forumPick):S.forumSelected.delete(el.dataset.forumPick);return;}if(el.dataset.reportFund){const f=D.funds.find(f=>f.code===el.dataset.reportFund);Object.assign(f,await objectStore.relations(f.code,{asOf:el.value}));S.focus=f.id;S.detail=f.id;return render();}if(el.name==='mode'&&el.closest('#settings-form')){el.form.querySelector('details').open=el.value==='custom';return;}if(el.dataset.eventPick){el.checked?S.selected.add(el.dataset.eventPick):S.selected.delete(el.dataset.eventPick);const b=document.querySelector('[data-act="ai-summary"]');if(b)b.disabled=!S.selected.size;return;}
 if(el.matches('[data-timeline-object]'))return selectTimeline(el.value);if(el.matches('[data-discussion-object]')){const id=el.value;S.discussionId=id;S.forumSelected.clear();S.activityLoading=id;render();if(id)await loadObjectStreams(id);if(S.discussionId===id){S.activityLoading='';if(S.view==='discussion')render();}return;}
 if(el.id==='source-object')return selectSource(el.value);
 if(el.id==='account-file'&&el.files[0])try{const data=JSON.parse(await el.files[0].text());if(data.format!=='zhijian-holdings')throw Error('持仓文件格式无效');saveAccount(data.items);}catch(err){toast(err.message);}}
function onInput(e){const el=e.target;if(el.name==='note'&&el.closest('[data-ai-note-form]')){S.aiNoteDrafts??={};S.aiNoteDrafts[el.closest('form').dataset.aiNoteForm]=el.value;}if(el.name==='question'&&el.closest('#ai-workbench, #v7-ai-form, #v15-analysis-ai-form'))S.aiQuestions[S.view]=el.value;if(el.id==='holding-search')search(el.value,$('#holding-results')).catch(err=>toast(err.message));if(el.id==='v7-q')search(el.value,$('#v7-results')).catch(err=>toast(err.message));
 if(el.dataset.amountIndex!==undefined){syncEditor();$('#editor-total').textContent=cash(editingRows.reduce((s,r)=>s+(Number(r.amount)||0),0));}
 if(el.matches('[data-timeline-search]')){S.timelineSearch=el.value;searchTimeline(el).catch(err=>toast(err.message));}
 if(el.matches('[data-discussion-search]')){S.discussionSearch=el.value;searchObjects(el,'discussion',S.discussionId.startsWith('stock')?'company':'fund').catch(err=>toast(err.message));}
 if(el.id==='source-object-query')searchObjects(el,'source',null).catch(err=>toast(err.message));
 if(el.id==='source-query'){S.sourceQuery=el.value;S.sourcePage=0;clearTimeout(onInput.t);onInput.t=setTimeout(()=>{const pos=el.selectionStart;render();$('#source-query').focus();$('#source-query').setSelectionRange(pos,pos);},250);}
 if(el.closest('#scenario-form')&&$('#scenario-result'))$('#scenario-result').innerHTML='';}


function holdingStatusText(f){return ({'via-target-etf':'本基金未披露直接股票，可查看目标ETF参考。','holds-funds':'来源列示持有基金，见上方明细。','source-missing':'公开来源暂缺股票明细。','no-stock-by-design':'当前分类与来源表未列示股票。','pending-retry':'当前尚未取得本基金或目标ETF的股票明细。'})[f.holdingStatus]||'来源未列示股票明细。';}
function heldFundsMarkup(f){const x=f.profile?.holdingExtra;if(!x?.heldFunds?.length)return '';return `<h3>持有基金</h3><small>来源表列值 · 报告日期未提供</small><div class="v8-related-list">${x.heldFunds.map(r=>`<button data-act="object-profile" data-id="fund${h(r.fundCode)}"><span>${h(r.fundName)}</span><small>${pct(r.weight)}</small><span>↗</span></button>`).join('')}</div>`;}
function eventLabels(e){return [...new Map((e.entities||[]).map(x=>[x.kind+'|'+x.code,x])).values()].map(x=>{const id=x.kind+x.code;const name=x.name||objectCards.get(id)?.name||D.funds.find(f=>f.id===id)?.name||D.stocks.find(s=>s.code===x.code)?.name||x.code;const label=({fund:'基金',stock:'股票',company:'企业',market:'市场',unassigned:'待归属'})[x.kind]||'关联对象';return `<span>${h(label)} · ${h(name)} ${h(x.code)}</span>`;}).join(' ');}

function aiPanel(){return `<section class="v15-ai-panel" aria-label="AI分析"><div class="v15-ai-panel-head">${icon('spark')}<h2>AI分析</h2>${S.view==='news'?'<span>勾选事件，或分析当前对象最近30条</span>':''}</div><form id="ai-workbench"><div class="v15-ai-presets"><button class="v15-button" name="preset" value="summary">${S.view==='news'?'整体与逐条摘要':'摘要'}</button><button class="v15-button" name="preset" value="impact">与持仓的关联</button><button class="v15-button" name="preset" value="differences">要点与分歧</button>${S.view==='sources'?'<button class="v15-button" name="preset" value="search">辅助查询</button>':''}</div><label class="v15-question"><input name="question" maxlength="2000" aria-label="AI提问" placeholder="也可以写下你想了解的问题" value="${h(S.aiQuestions[S.view]||'')}"><button class="v15-send" name="preset" value="custom" aria-label="发送分析问题">${icon('arrow')}</button></label></form><div class="v15-ai-status" data-ai-scope="${S.view}" aria-live="polite"></div></section>`;}

const fitMaterials=fitTextMaterials;
function portfolioNewsContext(events){const m=model(),codes=new Set(events.flatMap(e=>(e.entities||[]).filter(t=>['stock','company'].includes(t.kind)).map(t=>t.code)));return {id:'portfolio-context',text:'当前组合基金及资金比例：\n'+m.funds.map(f=>`${f.name} ${f.code}：${pct(f.share)}；持仓报告日${f.disclosure?.asOf||'待更新'}。\n`+f.holdings.filter(r=>codes.has(r.code)).map(r=>`${r.name} ${r.code}：占基金净资产${pct(r.weight)}，按当前金额折算占组合${pct(f.share*r.weight/100)}。`).join('\n')).join('\n'),date:today(),url:null};}
async function pageAI(data){
 const scope=S.view;if(scope==='news'){const preset=data.preset||'custom',events=S.selected.size?D.events.filter(x=>S.selected.has(x.id)):S.timelineId?eventSelection(D.events,timelineModel(),S.timelineMode,S.timelineId,today(),S.older):portfolioEvents(D.events,model(),S.timelineMode,today(),S.older);if(preset==='custom'&&!String(data.question||'').trim())return toast('请输入问题或选择上方选项');if(S.selected.size>29&&preset==='impact'||S.selected.size>30)return toast('每次最多分析30份材料；关联分析预留一份组合资料，请减少勾选。');const task=({summary:'news_summary',impact:'news_impact',differences:'news_differences'})[preset]||'news_ask',context=preset==='impact'?portfolioNewsContext(events.slice(0,29)):null;return startAI({task,scope,materials:events.slice(0,context?29:30).map(e=>({id:e.id})),question:data.question||'',work:(cfg,progress)=>analyzeEvents({events,cfg,task,question:data.question||'',context,progress})});}
 const preset=data.preset||'custom',questions={summary:'先写一段清楚的整体摘要，再按主题写简明要点。',impact:'说明材料与当前持仓的基金和公司有什么关联，按具体事件和持有路径讲清楚。',differences:'整理主要说法与分歧，区分原始事实、网友判断和待核事项。',search:'根据问题查找所给资料中的相关依据，列出已找到和未找到的信息。'};let materials=[];
 if(S.view==='library')materials=library.analysisMaterials();

 if(S.view==='sources'){
  const question=(data.question||'').trim();if(preset==='search'&&question){const hits=await objectStore.search(question,null,5);await Promise.allSettled(hits.map(x=>ensureObject(x.id)));if(!hits.length){const objects=await objectStore.objects();const explicit=objects.filter(x=>question.includes(x.code)||x.name.length>2&&question.includes(x.name)).slice(0,5);await Promise.allSettled(explicit.map(x=>ensureObject(x.id)));materials=explicit.flatMap(x=>evidenceMaterials(x.id,question));}else materials=hits.flatMap(x=>evidenceMaterials(x.id,question));}
  if(!materials.length)materials=evidenceMaterials(S.sourceId,data.question||'');if(S.selected.size)materials=materials.filter(x=>S.selected.has(x.id));
 }
 if(S.view==='discussion'){const ids=[...discussionIds(objectModel(S.discussionId),S.discussionId)];await Promise.all(ids.map(ensureForum));const posts=discussionRows(uniquePosts(D.forum.records.filter(r=>!S.forumSelected.size||S.forumSelected.has(r.id))),new Set(ids),S.forumDay,preset==='impact'?29:30).filter(r=>r.content||r.comments?.length);materials=forumMaterials(posts);}
 if(!materials.length)return toast(S.view==='library'?'请勾选要分析的收藏文字':'当前没有可分析材料，请选择对象或先读取资料');
 if(preset==='custom'&&!String(data.question||'').trim())return toast('请输入问题或选择上方选项');
 if(preset==='impact'){const m=model();materials=materials.slice(0,29);materials.push({id:'portfolio-context',text:'当前输入金额折算的资金占比（不含金额）：\n'+m.funds.map(f=>`${f.name} ${f.code}：${pct(f.share)}；报告日 ${f.disclosure?.asOf||'缺失'}；关联股票 ${f.holdings.slice(0,20).map(r=>`${r.name} ${r.code}（占基金净资产${pct(r.weight)}）`).join('、')}`).join('\n'),url:null,date:today()});}
 const task=S.view==='discussion'?({summary:'discussion_summary',impact:'discussion_impact',differences:'discussion_differences'}[preset]||'discussion_ask'):(preset==='summary'?'summary':'qa');
 return runAI(task,fitMaterials(materials),[questions[preset]||'',data.question||''].filter(Boolean).join('\n'));
}
function loadCachedForum(id,day){const k=id+'|'+day;if(localForumJobs.has(k))return;localForumJobs.set(k,(async()=>{try{const res=await fetch(apiURL('/api/forum?objectId='+encodeURIComponent(id)+'&date='+day));if(!res.ok)return;const data=await res.json();localForumStatus.set(k,data);if(data.records?.length)D.forum.records=mergePosts(D.forum.records,data.records);if(S.view==='discussion'&&S.forumDay===day)render();}catch{}})());}
function readingBatchMarkup(){if(!readingBatch?.status)return '';const b=readingBatch,label=['queued','running'].includes(b.status)?'正在补读':b.status==='complete'?'补读完成':'补读已结束';return `<p class="v8-muted" role="status">${h(label)} · ${h(b.date)} · ${b.finished||0}/${b.total||0} 个对象${b.status==='partial'?' · 部分来源尚未返回':''}</p>`;}
async function startReadingBatch(pageOnly=false){
 const owned=discussionIds(objectModel(S.discussionId),S.discussionId),rows=discussionRows(D.forum.records||[],owned,S.forumDay),ids=pageOnly?[...new Set(rows.filter(r=>r.coverage?.body!=='complete'||r.coverage?.comments!=='complete').map(r=>r.objectId))]:[...owned].filter(id=>/^(fund|stock)[0-9A-Z]{1,12}$/.test(id));
 if(!ids.length)return toast(pageOnly?'本页已有内容均已读取':'请先选择基金或股票');if(ids.length>256)return toast('请先选择一只基金或股票，再补读其关联内容');
 try{const r=await fetch(apiURL('/api/forum/batch'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({objectIds:ids,date:S.forumDay})}),d=await r.json();if(!r.ok)throw Error(d.error||'暂时无法启动补读');readingBatch={...d,scopeId:S.discussionId,loaded:[]};put('zhijian-forum-reading-v20',readingBatch);if(S.view==='discussion')render();pollReadingBatch(d.id);}catch(e){toast(e.message);}
}
async function pollReadingBatch(id){const token=++readerPoll;const poll=async()=>{if(token!==readerPoll)return;try{const r=await fetch(apiURL('/api/forum/batch?jobId='+encodeURIComponent(id))),d=await r.json();if(!r.ok)throw Error(d.error||'补读进度暂不可用');readingBatch={...readingBatch,...d};readingBatch.loaded??=[];
 for(const oid of d.completed||[])if(!readingBatch.loaded.includes(oid)){const res=await fetch(apiURL('/api/forum?objectId='+encodeURIComponent(oid)+'&date='+d.date));if(res.ok){const value=await res.json();D.forum.records=mergePosts(D.forum.records,value.records||[]);localForumStatus.set(oid+'|'+d.date,value);readingBatch.loaded.push(oid);}}
 put('zhijian-forum-reading-v20',readingBatch);if(S.view==='discussion')render();if(['queued','running'].includes(d.status))setTimeout(poll,3000);else{let region=$('#ai-completion-notices');if(!region){region=document.createElement('aside');region.id='ai-completion-notices';region.setAttribute('aria-live','polite');document.body.append(region);}region.querySelector('[data-reader-notice]')?.remove();const n=document.createElement('section');n.className='v18-ai-notice';n.dataset.readerNotice='true';n.innerHTML=`<strong>补读已结束</strong><p>${h(d.date)} · ${d.finished}/${d.total} 个对象${d.status==='partial'?' · 部分来源尚未返回':''}</p><div class="v7-actions">${btn('go-reader','查看帖子与评论')}${btn('dismiss-reader-notice','关闭提醒','','v15-text-link')}</div>`;region.append(n);}}
 catch(e){if(token!==readerPoll)return;if(S.view==='discussion')toast('补读仍在后台运行，正在重新连接进度');setTimeout(poll,15000);}};poll();}
function forumStatusMarkup(id){const owned=discussionIds(objectModel(id),id),values=[...localForumStatus].filter(([key])=>key.endsWith('|'+S.forumDay)&&owned.has(key.split('|')[0])).map(([,v])=>v);if(!values.length)return '';const running=values.some(v=>['queued','running'].includes(v.status)),partial=values.some(v=>v.status==='partial'),complete=values.some(v=>v.status==='complete');const label=running?'正在读取正文与评论，可继续浏览其他页面…':partial?'已保留读到的内容，剩余内容可继续读取。':complete?'本次读取已完成。':'';return `<p class="v8-muted" role="status">${h(label)}</p>`;}
async function fetchForumNow(postId=''){
 const day=S.forumDay,owned=discussionIds(objectModel(S.discussionId),S.discussionId),visible=discussionRows(D.forum.records||[],owned,day),row=postId?D.forum.records.find(r=>r.id===postId&&r.date===day):null,groups=new Map();
 for(const r of row?[row]:visible){if(!row&&r.coverage?.body==='complete'&&r.coverage?.comments==='complete')continue;const ids=groups.get(r.objectId)||[];if(/^(?:\d{1,24}|sina:\d{1,24}:\d{1,24})$/.test(r.id))ids.push(r.id);groups.set(r.objectId,ids);}
 if(!groups.size&&/^(fund|stock)[0-9A-Z]{1,12}$/.test(S.discussionId))groups.set(S.discussionId,[]);
 if(!groups.size)return toast('请选择基金、股票或需要读取的帖子');
 const entries=[...groups];if(!postId&&/^(fund|stock)[0-9A-Z]{1,12}$/.test(S.discussionId)&&!groups.has(S.discussionId))entries.unshift([S.discussionId,[]]);const tasks=entries.slice(0,8);let outstanding=tasks.length;S.activityLoading=S.discussionId||'portfolio';
 const done=()=>{if(--outstanding===0){S.activityLoading='';if(S.view==='discussion')render();toast('本次读取已结束，取得的正文与评论已保留');}};
 for(const [id,postIds] of tasks){
  const key=id+'|'+day;localForumStatus.set(key,{status:'queued'});
  try{const r=await fetch(apiURL('/api/forum'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({objectId:id,date:day,postIds:postIds.slice(0,30),allMissing:true})});const d=await r.json();if(!r.ok)throw Error(d.error||'当前服务不支持按需读取');
   const poll=async()=>{try{const res=await fetch(apiURL('/api/forum?objectId='+encodeURIComponent(id)+'&date='+day));if(!res.ok)throw Error('读取状态暂不可用');const x=await res.json();localForumStatus.set(key,x);if(x.records)D.forum.records=mergePosts(D.forum.records,x.records);if(S.view==='discussion'&&S.forumDay===day)render();if(['queued','running'].includes(x.status))setTimeout(poll,3000);else done();}catch(e){localForumStatus.set(key,{status:'partial',message:e.message});done();}};poll();
  }catch(e){localForumStatus.set(key,{status:'partial',message:e.message});done();toast(e.message);}
 }
 if(S.view==='discussion')render();
}

boot().catch(err=>{$('#v7-view').innerHTML='<div class="v7-empty">页面未能加载，请刷新重试。</div>';console.error(err);});
